package com.vynedam.stockai.controller; import com.vynedam.stockai.dto.UserDtos.*; import com.vynedam.stockai.model.User; import com.vynedam.stockai.service.UserAdminService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/users")@PreAuthorize("hasRole('SUPER_ADMIN')")public class UserAdminController{private final UserAdminService s;public UserAdminController(UserAdminService x){s=x;}@GetMapping List<User>list(){return s.list();}@PostMapping ResponseEntity<User>create(@Valid@RequestBody UserCreateRequest r){return ResponseEntity.status(201).body(s.create(r));}@PutMapping("/{id}")User update(@PathVariable String id,@Valid@RequestBody UserUpdateRequest r){return s.update(id,r);}@PatchMapping("/{id}/active")User active(@PathVariable String id,@RequestParam boolean value){return s.active(id,value);}}
